        y = erf(t.ravel())
        self._m = RBFInterpolator(t, y, kernel="linear")

    def __call__(self, x):
        tp = 6.0 * float(x) - 3.0
        return float(self._m([[tp]])[0])


_model = _RBFModel()


def program(x) -> float:
